        "scope": {
          "type": "string",
          "minLength": 1,
          "description": "Scope value for this primitive."
        },
        "precedence": {
          "type": "integer",
          "minimum": 0,
          "description": "Precedence value for this primitive."
        },
        "source_ref": {
          "type": [
            "string",
            "null"
          ],
          "description": "Reference to the source.",
