        "value": true,
        "source_layer_id": {
          "type": "string",
          "minLength": 1,
          "description": "Stable identifier for the source layer.",
          "examples": [
            "source_layer_example"
          ]
        },
        "visibility": {
          "$ref": "#/$defs/visibility_class",
          "description": "Visibility record for this primitive."
        },
        "env_gate_ids": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "description": "One entry in env gate ids.",
            "examples": [
              [
                "env_gate_example"
              ]
            ]
          },
          "description": "Stable identifiers for the env gate entries.",
          "examples": [
            [
              "env_gate_example"
            ]
          ]
        }
      },
      "additionalProperties": false
    },
    "merge_policy": {
      "type": "object",
      "required": [
        "policy_id",
        "strategy",
        "conflict_resolution"
      ],
