        },
        "conflict_resolution": {
          "enum": [
            "highest-precedence",
            "first-wins",
            "last-wins",
            "error"
          ],
          "description": "Allowed conflict resolution value."
        }
      },
      "additionalProperties": false
    },
    "visibility": {
      "type": "object",
      "required": [
        "model_visible_paths",
        "host_only_paths",
        "redacted_paths"
      ],
      "properties": {
        "model_visible_paths": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "description": "One entry in model visible paths."
          },
          "description": "Ordered model visible paths entries."
        },
        "host_only_paths": {
